const CODE_BF = `#include <cstdio>
#include <limits>
#include <string>
#include <vector>

struct Edge { int from, to; long long w; };
constexpr long long INF = std::numeric_limits<long long>::max();

// Returns false if a negative cycle is reachable from s.
bool bellmanFord(int n, const std::vector<Edge>& edges, int s,
                 std::vector<long long>& dist, std::vector<int>& parent, int& rounds) {
    dist.assign(n, INF);
    parent.assign(n, -1);
    dist[s] = 0;
    rounds = 0;
    for (int i = 0; i < n - 1; ++i) {  // at most V - 1 rounds
        bool changed = false;
        for (const auto& [u, v, w] : edges)
            if (dist[u] != INF && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                parent[v] = u;
                changed = true;
            }
        ++rounds;
        if (!changed) break;  // nothing moved: distances are final
    }
    for (const auto& [u, v, w] : edges)  // one extra check round
        if (dist[u] != INF && dist[u] + w < dist[v]) return false;
    return true;
}

int main() {
    const std::string name = "SABCD";
    // Edges listed in the worst order for this graph (see the animation).
    std::vector<Edge> edges = {{3, 4, -3}, {2, 4, 8}, {1, 3, 3}, {2, 3, 7},
                               {2, 1, 1},  {0, 2, 2}, {0, 1, 5}};
    std::vector<long long> dist;
    std::vector<int> parent;
    int rounds;
    bool ok = bellmanFord(5, edges, 0, dist, parent, rounds);
    std::printf("no negative cycle: %s, rounds used: %d\\n", ok ? "yes" : "no", rounds);
    for (int v = 0; v < 5; ++v) std::printf("dist(%c) = %lld\\n", name[v], dist[v]);

    edges.push_back({4, 2, -6});  // D -> B closes the cycle B -> A -> C -> D -> B
    ok = bellmanFord(5, edges, 0, dist, parent, rounds);
    std::printf("after adding D->B (-6): no negative cycle: %s\\n", ok ? "yes" : "no");
}`;
