const CODE_CP = `#include <algorithm>
#include <cstdio>
#include <queue>
#include <string>
#include <vector>

// Earliest finish time of a project = longest path in a DAG of tasks.
struct Task { std::string name; int hours; std::vector<int> after; };

int main() {
    std::vector<Task> tasks = {
        {"recon", 3, {}},              // 0
        {"plan", 2, {0}},              // 1
        {"clear route", 4, {1}},       // 2
        {"build bridge", 7, {0}},      // 3
        {"stage supplies", 5, {1}},    // 4
        {"move convoy", 2, {2, 3}},    // 5
        {"set up base", 3, {4, 5}},    // 6
    };
    const int n = int(tasks.size());
    std::vector<std::vector<int>> next(n);
    std::vector<int> indeg(n, 0);
    for (int v = 0; v < n; ++v)
        for (int u : tasks[v].after) { next[u].push_back(v); ++indeg[v]; }

    // Kahn's algorithm gives a topological order.
    std::queue<int> q;
    for (int v = 0; v < n; ++v) if (indeg[v] == 0) q.push(v);
    std::vector<int> order;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : next[u]) if (--indeg[v] == 0) q.push(v);
    }

    // Relax edges in topological order, maximizing instead of minimizing.
    std::vector<int> start(n, 0), parent(n, -1);
    for (int u : order)
        for (int v : next[u])
            if (start[u] + tasks[u].hours > start[v]) {
                start[v] = start[u] + tasks[u].hours;
                parent[v] = u;
            }

    int last = 0;
    for (int v = 0; v < n; ++v) {
        std::printf("%-15s starts at hour %2d\\n", tasks[v].name.c_str(), start[v]);
        if (start[v] + tasks[v].hours > start[last] + tasks[last].hours) last = v;
    }
    std::vector<std::string> path;
    for (int v = last; v != -1; v = parent[v]) path.push_back(tasks[v].name);
    std::reverse(path.begin(), path.end());
    std::printf("finish: hour %d\\ncritical path:", start[last] + tasks[last].hours);
    for (const auto& s : path) std::printf(" [%s]", s.c_str());
    std::printf("\\n");
}`;
